#' Valley detection and centroidization
#' 
#' Checks envelopes calculated by envelope for valleys and extracts centroids or intensoids.
#' 
#' @param profiles List of stick profiles as generated by envelope.
#' @param detect To return either "centroid", "intensoid" or "valley".
#' @param plotit Should results be plotted, TRUE/FALSE?
#' @param verbose Verbose, TRUE/FALSE?
#' 
#' @section Definitions:
#'   Valley: local profile minimum, i.e. any envelope stick flanked by two other sticks of higher abundance.
#'   
#'   Stick: see envelope.
#'   
#'   Centroid mass: intensity-weighted sum of the m/z of sticks between two valleys.
#'   
#'   Centroid intensity: profile area between two valleys (mean of upper and lower sum of stick intensities),
#'     normalized to the maximum centroid area of the envelope.
#'   
#'   Intensoid mass: m/z of the most intense stick between two valleys.
#'   
#'   Intensoid intensity: intensity of the most intensive stick between two valleys, normalized to the most intense intensoid.
#' 
#' @note Too low stick discretization leads to imprecision in valley, centroid and intensoid characteristics.

#' @return List with length equal to length of list profiles, with equal names of list entries.
#' Each entry in that list contains the centroids, intensoids or valleys of the envelope in two columns:
#' \item{m/z}{m/z}
#' \item{abundance}{Area (centroid) or abundance (intensoid, valley)}
#' 
#' @author Martin Loos, Christian Gerber
#' 
#' @seealso envelope, isopattern
#' 
#' @examples
#' data(isotopes)
#' data(chemforms)
#' pattern <- isopattern(
#'   isotopes,
#'   chemforms,
#'   threshold=0.1,
#'   plotit=TRUE,
#'   charge=FALSE,
#'   emass=0.00054858,
#'   algo=1
#' )
#' 
#' profiles <- envelope(
#'     pattern,
#'     ppm=FALSE,
#'     dmz=0.0001,   
#'     frac=1/4,
#'     env="Gaussian",
#'     resolution=1E6,
#'     plotit=TRUE
#' )
#' 
#' centro <- vdetect(
#'   profiles,
#'   detect="centroid",
#'   plotit=TRUE
#' )
#' 
#' @importFrom graphics points
#' @export
vdetect <-
function(
	profiles,
	detect="centroid",
	plotit=TRUE,
	verbose = TRUE){

    ############################################################################
    # (1) issue warnings #######################################################
    if(length(profiles[[1]])<2 || !all(colnames(profiles[[1]])[1:2] == c("m/z", "abundance"))) stop("WARNING: profile has invalid entries\n")
    if(any(detect==c("centroid","intensoid","valley"))==FALSE) stop("WARNING: invalid detect argument")
    if(plotit!="TRUE"&plotit!="FALSE") stop("WARNING: plotit invalid. TRUE, FALSE.\n")
	if(!is.logical(verbose)) stop("invalid verbose")
    options(digits = 10);
    ############################################################################
    # (2) detect ###############################################################
    if(verbose) message(paste0("Detect ", detect, "s... "))
    getlist <- list(0);
    for(i in 1:length(profiles)){
        if(detect=="centroid") return_type <- 0
        if(detect=="intensoid") return_type <- 1
        if(detect=="valley") return_type <- 2  
        # m:     double array of profile masses
        # a:     double array of profile abundances
        # return type: 0=centroid / 1=intensoid / 2=valley
		out <- .Call("iso_centroid_Call",
			f1 = as.double(profiles[[i]][,1]), # m
			a1 = as.double(profiles[[i]][,2]), # a
			t1 = as.integer(return_type),
			PACKAGE="enviPat"
		)
		if(!length(out[[1]])) getlist[[i]] <- "error" else{
			out2 <- matrix(ncol = 2, nrow = length(out[[1]]))
			out2[,1] <- out[[1]]
			out2[,2] <- out[[2]]
			colnames(out2) <- c("m/z","abundance")
			getlist[[i]] <- out2
			if(plotit==TRUE){
				plot(profiles[[i]][,1],profiles[[i]][,2],type="h",xlab="m/z",ylab="Relative abundance",main=names(profiles)[i])
				if(detect=="valley") points(out[[1]],out[[2]],col="red",type="h") else points(out[[1]],out[[2]],col="red",type="h",lwd=2);
			}
		}
    }
	names(getlist) <- names(profiles)
    if(verbose) message(" done.")
    ############################################################################
    # (3) output ###############################################################
    #if(detect=="centroid") assign(detect,getlist);return(centroid);
    #if(detect=="intensoid") assign(detect,getlist);return(centroid);
    #if(detect=="valley") assign(detect,getlist);return(centroid);
    return(getlist);
    ############################################################################

}
